  "Qual campeão é um golem de pedra, do tamanho de uma montanha, que lança rochas?": "Quel champion est un golem de pierre grand comme une montagne qui lance des rochers ?",
  "Qual é o sobrenome da família de Katarina e Cassiopeia?": "Quel est le nom de famille de Katarina et Cassiopeia ?",
  "Qual campeão é conhecido como o Olho do Crepúsculo?": "Quel champion est connu comme l’Œil du crépuscule ?",
