  "Qual campeão se considera um artista e é chamado de Virtuoso?": "Quel champion se considère comme un artiste et est surnommé le Virtuose ?",
  "Qual campeã é sacerdotisa de Nagakabouros, deus do mar de Águas de Sentina?": "Quelle championne est prêtresse de Nagakabouros, dieu de la mer de Bilgewater ?",
  "De qual antiga cidade, destruída pelo Vazio, vem Zilean?": "De quelle ancienne ville, détruite par le Néant, vient Zilean ?",
  "Qual campeã Darkin é uma matilha de cães, cada um com uma parte da lâmina?": "Quelle championne darkin est une meute de chiens, chacun portant une partie de la lame ?",
