  "Qual campeão de Targon é um guerreiro cujo manto passa a outro mortal quando ele morre?": "Quel champion de Targon est un guerrier dont le manteau passe à un autre mortel quand il meurt ?",
  "Qual campeã é uma camaleoa Vastaya de Ixtal que muda de forma?": "Quelle championne est une caméléon vastaya d’Ixtal qui change de forme ?",
