  "Você tem {n} tentativas. Só valem nomes de campeões: comece a digitar e escolha na lista. Uma vez por dia, a qualquer momento, dá para pedir uma dica, que revela uma característica que você ainda não acertou. A dica gasta uma tentativa. Um campeão novo aparece todo dia à meia-noite (horário de Brasília), diferente para cada jogador.": "Tu as {n} essais. Seuls les noms de champions comptent : commence à taper et choisis dans la liste. Une fois par jour, à tout moment, tu peux demander un indice, qui révèle une caractéristique que tu n’as pas encore trouvée. L’indice coûte un essai. Un nouveau champion apparaît chaque jour à minuit (heure de Brasília), différent pour chaque joueur.",
