  "Você ganha abóboras jogando: cada partida concluída, em qualquer jogo, rende abóboras.": "Tu gagnes des citrouilles en jouant : chaque partie terminée, dans n’importe quel jeu, rapporte des citrouilles.",
  "No Na Medida, o Diário e a Ranqueada rendem abóboras pelo dia completo (as 5 rodadas); no modo Livre, a cada 5 rodadas.": "Dans Na Medida, le Quotidien et le Classé rapportent des citrouilles pour la journée complète (les 5 manches) ; en mode Libre, toutes les 5 manches.",
  "Dá para ganhar até {num} abóboras por dia. O limite zera à meia-noite (horário de Brasília).": "Tu peux gagner jusqu’à {num} citrouilles par jour. La limite est remise à zéro à minuit (heure de Brasília).",
  "A cada {num} abóboras você sobe um nível e libera a recompensa dele.": "Toutes les {num} citrouilles, tu montes d’un niveau et débloques sa récompense.",
