  "✓ Completo": "✓ Terminé",
  "★ Premium": "★ Premium",
  "Grátis": "Gratuit",
  "✓ Resgatado": "✓ Récupéré",
  "Termine partidas para ganhar abóboras e encher a barra: ao completá-la, você sobe de nível e libera a recompensa dele. Cada partida concluída, ranqueada ou não, rende abóboras (há um limite por dia, que zera à meia-noite, horário de Brasília).": "Termine des parties pour gagner des citrouilles et remplir la barre : quand elle est pleine, tu montes de niveau et débloques la récompense de ce niveau. Chaque partie terminée, classée ou non, rapporte des citrouilles (il y a une limite quotidienne qui se réinitialise à minuit, heure de Brasília).",
  "Entre na sua conta para participar do passe de batalha.": "Connecte-toi à ton compte pour participer au passe de combat.",
  "O passe de batalha precisa de conexão com o servidor do site, que não está disponível nesta versão.": "Le passe de combat a besoin d’une connexion au serveur du site, qui n’est pas disponible dans cette version.",
