  "Objetivo garantido!": "Objectif sécurisé !",
  "O objetivo sobreviveu!": "L’objectif a survécu !",
  "Roubaram o objetivo!": "L’objectif a été volé !",
  "Desafio de timing · League of Legends": "Défi de timing · League of Legends",
  "Um objetivo está quase morrendo e o time inimigo está de olho. Use o <b>Golpear</b> na hora certa para <b>garantir o objetivo</b>: os pontos dependem de quão rápido você golpeia depois que a vida do objetivo entra no dano do Golpear.": "Un objectif est sur le point de mourir et l’équipe adverse guette. Utilise <b>Châtiment</b> au bon moment pour <b>sécuriser l’objectif</b> : les points dépendent de ta rapidité après que les PV de l’objectif sont entrés dans les dégâts de Châtiment.",
  "Observe": "Observe",
  "A vida do objetivo cai com o dano dos aliados e dos adversários, inclusive o seu. Cada time tem topo, selva, meio e atirador, e você é o selva do time azul.": "Les PV de l’objectif baissent avec les dégâts des alliés et des ennemis, le tien inclus. Chaque équipe a un top, un jungler, un mid et un tireur, et tu es le jungler de l’équipe bleue.",
  "Golpeie": "Frappe",
  "O Golpear mata se a vida for menor ou igual ao dano dele (600, 900 ou 1200 baseado no nível). Se errar, a rodada continua: se o seu time ficar com o objetivo vale 25 pontos; se for o time inimigo, 0.": "Châtiment tue si les PV sont inférieurs ou égaux à ses dégâts (600, 900 ou 1200 selon le niveau). Si tu rates, la manche continue : si ton équipe prend l’objectif, cela vaut 25 points ; si c’est l’équipe adverse, 0.",
  "O botão Q do seu campeão também machuca o objetivo. Use para finalizar ou combar com o Golpear.": "Le bouton Q de ton champion blesse aussi l’objectif. Utilise-le pour l’achever ou pour combiner avec Châtiment.",
  "As {rodadas} rodadas formam uma partida, com os mesmos campeões do início ao fim. Até <b>100 pontos</b> por rodada. Teclas: <b>F</b> ou <b>Espaço</b> = Golpear · <b>Q</b> = habilidade.": "Les {rodadas} manches forment une partie, avec les mêmes champions du début à la fin. Jusqu’à <b>100 points</b> par manche. Touches : <b>F</b> ou <b>Espace</b> = Châtiment · <b>Q</b> = compétence.",
  "Seu recorde: <b>{n}</b> pontos": "Ton record : <b>{n}</b> points",
  "JOGAR": "JOUER",
  "Rodada {n} de {total}": "Manche {n} sur {total}",
  "Rodada {n}": "Manche {n}",
  "Você é o selva do time azul": "Tu es le jungler de l’équipe bleue",
  "Q: toque para a Onda Sônica; em até {janela}s toque de novo para o Chute, que bate mais quanto menos vida o objetivo tem. Recarga {seg}s.": "Q : appuie pour l’Onde sonique ; en {janela} s appuie à nouveau pour le Coup de pied, plus fort quand l’objectif a moins de PV. Récupération {seg} s.",
  "Q: toque rápido para uma estocada ({dano}); segurando, causa mais dano.": "Q : appui bref pour une estocade ({dano}) ; en maintenant, inflige plus de dégâts.",
  "Q: arma o seu próximo ataque (até {janela}s) com +{dano} de dano; cada golpe seu corta 0,5s da recarga. Recarga {seg}s.": "Q : arme ta prochaine attaque (jusqu’à {janela} s) avec +{dano} de dégâts ; chacun de tes coups retire 0,5 s à la récupération. Récupération {seg} s.",
  "Q: {dano} de dano. Recarga {seg}s.": "Q : {dano} de dégâts. Récupération {seg} s.",
  "Ataque armado! O seu próximo golpe causa dano extra.": "Attaque armée ! Ton prochain coup inflige des dégâts supplémentaires.",
  "Perdeu a janela do segundo Q: a recarga começou.": "Fenêtre du second Q ratée : la récupération a commencé.",
  "Segurou demais! A recarga é a metade.": "Maintenu trop longtemps ! La récupération est réduite de moitié.",
  "Você está no nível <b>{nivel}</b>: o dano do seu Golpear é de <b>{smite}</b>. Golpeie quando a vida do {obj} for <b>menor ou igual</b> a esse valor, o mais perto possível.": "Tu es au niveau <b>{nivel}</b> : ton Châtiment inflige <b>{smite}</b> de dégâts. Frappe quand les PV de {obj} sont <b>inférieurs ou égaux</b> à cette valeur, au plus près possible.",
  "Golpeie o {obj} com o Golpear no momento certo!": "Frappe {obj} avec Châtiment au bon moment !",
  "Você golpeou <b>{seg}s</b> depois de a vida do {obj} entrar no dano do Golpear ({smite}).": "Tu as utilisé Châtiment <b>{seg} s</b> après que les PV de {obj} sont entrés dans les dégâts de Châtiment ({smite}).",
  "Ele ainda tinha <b>{vida}</b> de vida, <b>{faltou}</b> acima do dano do Golpear ({smite}). O time inimigo levou o objetivo.": "Il lui restait <b>{vida}</b> PV, soit <b>{faltou}</b> au-dessus des dégâts de Châtiment ({smite}). L’équipe adverse a pris l’objectif.",
  "O {obj} morreu antes do seu Golpear.": "{obj} est mort avant ton Châtiment.",
  "A sua habilidade derrubou o {obj} antes do Golpear. Só o Golpear garante o objetivo!": "Ta compétence a abattu {obj} avant Châtiment. Seul Châtiment sécurise l’objectif !",
  "O time inimigo levou o {obj}: o golpe final foi de {quem}.": "L’équipe adverse a pris {obj} : le coup final est de {quem}.",
  "Seu time derrubou o {obj} antes do seu Golpear (golpe final de {quem}).": "Ton équipe a abattu {obj} avant ton Châtiment (coup final de {quem}).",
