  "Cuidado": "Attention",
  "O Caçador inimigo também usa Golpear quando a vida do objetivo estiver perto do dano do Golpear.": "Le jungler adverse utilise aussi Châtiment quand les PV de l’objectif sont proches des dégâts de Châtiment.",
