  "Partidas do dia:": "Parties du jour :",
  "as primeiras partidas do dia valem PDR, com a conta conectada. Em alguns jogos vale só a primeira, em outros as 2 primeiras.": "les premières parties du jour rapportent des PDR, une fois connecté. Dans certains jeux seule la première compte, dans d’autres les 2 premières.",
  "+1 Pinstouro (pulo) por partida (3 no total)": "+1 Pinstouro (saut) par partie (3 au total)",
