  "Elos:": "Rangs :",
  "Ferro, Bronze, Prata, Ouro, Platina, Esmeralda e Diamante, com 3 divisões cada. Ao alcançar 100 PDR, você avança para a próxima divisão.": "Fer, Bronze, Argent, Or, Platine, Émeraude et Diamant, avec 3 divisions chacun. À 100 PDR, tu passes à la division suivante.",
  "Mestre, Grão-Mestre e Desafiante:": "Maître, Grand Maître et Challenger :",
  "depois do Diamante 1 vem o Mestre. Todo dia à meia-noite, pela ordem de PDR, os 100 melhores com 500+ PDR viram Desafiante e os 200 seguintes com 200+ PDR, Grão-Mestre.": "après Diamant 1 vient Maître. Chaque jour à minuit, selon les PDR, les 100 meilleurs avec 500+ PDR deviennent Challenger et les 200 suivants avec 200+ PDR, Grand Maître.",
  "Queda:": "Descente :",
  "perdendo PDR, a divisão desce até 0. Perdendo com 0, volta para a divisão anterior com 75 PDR. Ferro 3 não cai.": "en perdant des PDR, la division descend jusqu’à 0. Perdre à 0 te ramène à la division précédente avec 75 PDR. Fer 3 ne descend pas.",
