  "Descubra a sua palavra do dia em 6 tentativas (cada jogador tem uma palavra diferente). Todas as respostas são nomes do universo de League of Legends: campeões, regiões e lugares de Runeterra, itens, monstros do mapa e personagens da lore.": "Trouve ton mot du jour en 6 essais (chaque joueur a un mot différent). Toutes les réponses sont des noms de l’univers de League of Legends : champions, régions et lieux de Runeterra, objets, monstres de la carte et personnages du lore.",
  "A palavra do dia pode ter de 5 a 7 letras. Depois de cada tentativa, as peças mostram o quão perto você está.": "Le mot du jour peut avoir de 5 à 7 lettres. Après chaque essai, les tuiles montrent à quel point tu es proche.",
  "Toque num quadrado para escolher onde escrever: dá para preencher primeiro as letras que você já sabe, em qualquer posição.": "Touche une case pour choisir où écrire : tu peux d’abord remplir les lettres que tu connais déjà, à n’importe quelle position.",
  "A letra": "La lettre",
  "está na palavra e no lugar certo.": "est dans le mot et à la bonne place.",
  "está na palavra, mas em outro lugar.": "est dans le mot, mais à une autre place.",
  "não está na palavra.": "n’est pas dans le mot.",
  "Vale tentar qualquer palavra comum do português ou do universo de LoL com o mesmo número de letras. Acentos e apóstrofos são preenchidos sozinhos e não contam nas dicas. As palavras podem ter letras repetidas.": "Tu peux essayer n’importe quel mot courant du portugais ou de l’univers de LoL avec le même nombre de lettres. Les accents et apostrophes se remplissent tout seuls et ne comptent pas dans les indices. Les mots peuvent avoir des lettres répétées.",
