  "Você não tem anúncios abertos. Para vender um jogador, abra a ficha dele em Meu elenco e toque em Anunciar.": "Tu n’as aucune annonce ouverte. Pour vendre un joueur, ouvre sa fiche dans Mon effectif et touche Mettre en vente.",
