  "🏆 Campeão": "🏆 Champion",
  "Chaveamento": "Tableau",
  "16 equipes (técnicos classificados e equipes do sistema). De segunda a sexta, 2 jogos por dia contra equipes diferentes (melhor de 1). Os 4 melhores jogam as semifinais no sábado (melhor de 3) e a final no domingo (melhor de 5). Contra a equipe de outro técnico você joga contra o bot dela, e cada um conta o próprio resultado. O campeão ganha vaga no {x1}.": "16 équipes (coachs qualifiés et équipes du système). Du lundi au vendredi, 2 matchs par jour contre des équipes différentes (au meilleur des 1). Les 4 meilleures jouent les demi-finales le samedi (au meilleur des 3) et la finale le dimanche (au meilleur des 5). Contre l’équipe d’un autre coach, tu affrontes son bot, et chacun compte son propre résultat. Le champion gagne une place au {x1}.",
  "16 equipes em 4 grupos de 4, sorteados por potes de poder. Segunda: treino. Terça a quinta: 2 jogos por dia contra o seu grupo (cada adversário duas vezes). Sexta: quartas de final (melhor de 3) com os 2 primeiros de cada grupo; sábado, semifinais (melhor de 3); domingo, a final (melhor de 5).": "16 équipes en 4 groupes de 4, tirées au sort par chapeaux de puissance. Lundi : entraînement. Du mardi au jeudi : 2 matchs par jour contre ton groupe (chaque adversaire deux fois). Vendredi : quarts de finale (au meilleur des 3) avec les 2 premiers de chaque groupe ; samedi, demi-finales (au meilleur des 3) ; dimanche, la finale (au meilleur des 5).",
  "Os 2 primeiros sobem para a {x1}; os demais continuam na {x2}.": "Les 2 premiers montent en {x1} ; les autres restent en {x2}.",
  "Os 2 primeiros ganham vaga na {x1}{x2}. Não há rebaixamento.": "Les 2 premiers gagnent une place en {x1}{x2}. Il n’y a pas de relégation.",
