  "{x8} campeões favoritos": "{x8} champions favoris",
  ". Quanto mais ele joga com um campeão, mais maestria ganha: a cada mapa são {x9} pontos na vitória e {x10} na derrota. Com {x11} pontos ele entra na lista de favoritos e, ao jogar com o campeão, ganha um bônus de Poder que cresce com o nível ({x12}).": ". Plus il joue un champion, plus il gagne de maîtrise : chaque carte rapporte {x9} points pour une victoire et {x10} pour une défaite. Avec {x11} points, il entre dans la liste des favoris et, en jouant ce champion, obtient un bonus de Puissance qui croît avec le niveau ({x12}).",
  "Nenhum campeão com esses filtros.": "Aucun champion avec ces filtres.",
