  "Formato:": "Format :",
  "16 equipes. Segunda a sexta: 2 jogos por dia contra equipes diferentes (melhor de 1). Sábado: semifinais com os 4 melhores (melhor de 3). Domingo: final (melhor de 5). O campeão ganha vaga no {x9}.": "16 équipes. Du lundi au vendredi : 2 matchs par jour contre des équipes différentes (au meilleur des 1). Samedi : demi-finales avec les 4 meilleures (au meilleur des 3). Dimanche : finale (au meilleur des 5). Le champion gagne une place au {x9}.",
  "Semana 4 · {x13} a {x14}": "Semaine 4 · {x13} au {x14}",
  "2 primeiros da {x17} na semana 2 ou 3, ou campeão da {x18}.": "2 premiers de la {x17} en semaine 2 ou 3, ou champion de la {x18}.",
  "16 equipes em 4 grupos. Segunda: treino (2 jogos, sem pontos, só XP e Maestria). Terça a quinta: 2 jogos por dia no grupo (cada adversário duas vezes). Sexta: quartas (melhor de 3). Sábado: semifinais (melhor de 3). Domingo: final (melhor de 5).": "16 équipes en 4 groupes. Lundi : entraînement (2 matchs, sans points, seulement XP et Maîtrise). Du mardi au jeudi : 2 matchs par jour dans le groupe (chaque adversaire deux fois). Vendredi : quarts (au meilleur des 3). Samedi : demi-finales (au meilleur des 3). Dimanche : finale (au meilleur des 5).",
