  "Ele vai para o seu inventário. Para escalá-lo como titular você efetiva um contrato (1 semana ou 1 temporada) com salário em créditos.": "Il va dans ton inventaire. Pour l’aligner comme titulaire, tu actives un contrat (1 semaine ou 1 saison) avec un salaire en crédits.",
