  "Preço fixo em Rift Coins. O jogador continua no seu elenco até alguém comprar, e você pode cancelar quando quiser.": "Prix fixe en Rift Coins. Le joueur reste dans ton effectif jusqu’à ce que quelqu’un l’achète, et tu peux annuler quand tu veux.",
