  "O contrato dele ({x1} semana(s) já pagas) só acaba quando alguém comprar: você recebe de volta": "Son contrat ({x1} semaine(s) déjà payée(s)) ne prend fin que lorsque quelqu’un l’achète : tu récupères",
  "(50% do que sobrou) e o comprador recebe o jogador sem contrato.": "(50 % du reste) et l’acheteur reçoit le joueur sans contrat.",
  "As estrelas e as cópias repetidas dele vão junto com a venda. Se o comprador já tiver este Legado, o jogador vira cópia para ele.": "Ses étoiles et ses copies en double partent avec la vente. Si l’acheteur a déjà ce joueur Héritage, le joueur devient une copie pour lui.",
  "Esse jogador é titular. Se ele for vendido, a vaga é preenchida por um reserva ou por um substituto fraco.": "Ce joueur est titulaire. S’il est vendu, la place est prise par un remplaçant ou un faible substitut.",
