  "Desafie outro time para uma partida de treino (scrim) de verdade: picks e bans, depois a simulação com os campeões. Não vale pontos de campeonato. Você pode jogar quantos quiser por dia, mas só os": "Défie une autre équipe pour un vrai match d’entraînement (scrim) : picks et bans, puis la simulation avec les champions. Il ne compte pas pour les points du championnat. Tu peux en jouer autant que tu veux par jour, mais seuls les",
