  ": os cinco titulares contam inteiros e os melhores reservas contam {x2}. Cada jogador conta uma vez, e a conta é comprimida para que ter muitos astros não exploda a renda. Bônus atual:": " : les cinq titulaires comptent en entier et les meilleurs remplaçants comptent {x2}. Chaque joueur compte une fois, et le calcul est compressé pour qu’avoir beaucoup de stars ne fasse pas exploser les revenus. Bonus actuel :",
