  "Por que não consigo escalar um jogador?": "Pourquoi ne puis-je pas aligner un joueur ?",
  "Ele precisa de contrato ativo. Abra a ficha e efetive um contrato de 1 semana ou 1 temporada.": "Il lui faut un contrat actif. Ouvre sa fiche et active un contrat de 1 semaine ou 1 saison.",
