  "Jogador em vaga que não é a dele (nem a posição secundária) rende 75% do Poder.": "Un joueur à une place qui n’est pas la sienne (ni son poste secondaire) rend 75 % de sa Puissance.",
  "Qual a diferença entre créditos e RC?": "Quelle est la différence entre crédits et RC ?",
  "Créditos são do clube (salários, contratos, treino). RC é da sua conta (baús, mercado entre usuários, nome do time).": "Les crédits appartiennent au club (salaires, contrats, entraînement). Les RC appartiennent à ton compte (coffres, marché entre joueurs, nom de l’équipe).",
